let calendarMonthOffset=0;
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const defaultState={done:{},tasks:[],notes:{},lastRead:{},minutes:0,agenda:[],targets:{daily:60,weekly:420,monthly:1800},preferences:{theme:'light',appLanguage:'id',learningLanguage:'English',notifications:true},bookmarks:{},readingDone:{},focusSessions:[]};
let state;
try { state={...defaultState,...JSON.parse(localStorage.getItem('mas-state')||'{}')}; } catch { state={...defaultState}; }
state.done=state.done||{};state.tasks=Array.isArray(state.tasks)?state.tasks:[];state.notes=state.notes||{};state.lastRead=state.lastRead||{};
state.preferences={...defaultState.preferences,...(state.preferences||{})};state.agenda=Array.isArray(state.agenda)?state.agenda:[];state.targets={...defaultState.targets,...(state.targets||{})};state.bookmarks=state.bookmarks||{};state.readingDone=state.readingDone||{};state.focusSessions=Array.isArray(state.focusSessions)?state.focusSessions.filter(x=>x&&typeof x==='object'):[];state.minutes=Math.max(0,Number(state.minutes)||0);
