function save(){localStorage.setItem('mas-state',JSON.stringify(state));scheduleCloudSave(state);renderStats()}
function toast(t){let e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),2600)}
const dbp=new Promise((resolve,reject)=>{let r=indexedDB.open('academic-space-db',1);r.onupgradeneeded=()=>r.result.createObjectStore('pdfs',{keyPath:'path'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function dbPut(record){let db=await dbp;return new Promise((res,rej)=>{let tx=db.transaction('pdfs','readwrite');tx.objectStore('pdfs').put(record);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
async function dbGet(path){let db=await dbp;return new Promise((res,rej)=>{let r=db.transaction('pdfs').objectStore('pdfs').get(path);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function dbAll(){let db=await dbp;return new Promise((res,rej)=>{let r=db.transaction('pdfs').objectStore('pdfs').getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function progress(id){let c=courses.find(x=>x.id===id);if(!c||!c.units.length)return 0;let n=c.units.filter((u,i)=>state.done[id+'-'+i]).length;return Math.round(n/c.units.length*100)}
function renderStats(){let total=courses.reduce((a,c)=>a+c.units.length,0),done=Object.values(state.done).filter(Boolean).length;let a=$('#overall');if(a)a.textContent=Math.round(done/total*100)+'%';let b=$('#donecount');if(b)b.textContent=done+' / '+total;let m=$('#minutes');if(m)m.textContent=Math.floor(state.minutes/60)+' jam';let t=$('#targetDailyDisplay');if(t)t.textContent=(state.targets.daily||60)+' menit'}
function nav(){let items=['Dashboard','Ruang Belajar','Perpustakaan','AI Tutor','Kalender','Roadmap','Progres','Laporan','Pengaturan'],icons=['home','book','library','spark','calendar','route','progress','report','settings'];return `<aside class="sidebar"><div class="brand"><span class="brandmark">${iconSvg('graduation')}</span><span>My Academic<br>Space</span></div><div class="profile"><div class="avatar">${iconSvg('user')}</div><div><b>Shoupay</b><div class="muted">Belajar Tanpa Batas</div><small style="color:#08a45a">● Online</small></div></div><div class="nav">${items.map((x,i)=>`<button data-page="${x}" class="${page===x?'active':''}"><span class="navicon">${iconSvg(icons[i])}</span>${x}</button>`).join('')}</div><div class="sidefoot">${iconSvg('cloud')} <b id="cloudStatus">Memeriksa koneksi cloud…</b><br><span class="muted">Progress, tugas, dan catatan disimpan lokal serta disinkronkan ke Supabase saat tersedia.</span></div></aside>`}

function header(){return `<header class="top"><div><h1>Selamat datang kembali, Shoupay</h1><p>Terus belajar, wujudkan impianmu menjadi lebih ahli.</p></div><input id="globalSearch" class="search" placeholder="⌕  Cari materi, buku, atau topik..."></header>`}
function statCards(){let done=Object.values(state.done).filter(Boolean).length,total=courses.reduce((a,c)=>a+c.units.length,0),target=state.targets.daily||60,days=new Set(state.focusSessions.map(x=>x.date)),streak=0,dt=new Date();for(let i=0;i<366;i++){let day=`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;if(!days.has(day)){if(i===0){dt.setDate(dt.getDate()-1);continue;}break;}streak++;dt.setDate(dt.getDate()-1)}return `<section class="grid stats"><div class="stat"><div class="k">Target Harian</div><strong id="targetDailyDisplay">${target} menit</strong><small>Target belajar per hari</small></div><div class="stat"><div class="k">Progres Keseluruhan</div><strong id="overall">${Math.round(done/total*100)}%</strong><small id="donecount">${done} / ${total} materi selesai</small></div><div class="stat"><div class="k">Streak Belajar</div><strong>${streak} hari</strong><small>${streak?'Konsisten tercatat':'Mulai sesi fokus hari ini'}</small></div><div class="stat"><div class="k">Waktu Belajar</div><strong id="minutes">${Math.floor(state.minutes/60)} jam</strong><small>Akumulasi sesi fokus</small></div></section>`}
function dashboard(){
 const done=Object.values(state.done).filter(Boolean).length,total=courses.reduce((a,c)=>a+c.units.length,0),pct=Math.round(done/total*100),target=state.targets.daily||60;
 const active=courses.find(c=>c.units.some((u,i)=>!state.done[c.id+'-'+i]))||courses[0];
 const next=active.units.find((u,i)=>!state.done[active.id+'-'+i])||active.units[0];
 const days=['Min','Sen','Sel','Rab','Kam','Jum','Sab'],today=new Date(),monthStart=new Date(today.getFullYear(),today.getMonth(),1),monthDays=new Date(today.getFullYear(),today.getMonth()+1,0).getDate(),offset=monthStart.getDay();
 const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 const todayAgenda=state.agenda.filter(a=>a.date===localDate()).sort((a,b)=>(a.time||'').localeCompare(b.time||''));
 const roadmap=courses.slice(0,4);
 return `<section class="welcome-strip"><div><span class="eyebrow">RUANG BELAJAR PRIBADI</span><h1>Selamat datang, Shoupay! <span>👋</span></h1><p>Terus belajar, wujudkan impianmu menjadi lebih ahli.</p></div><div class="welcome-date">${today.toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div></section>
 <section class="grid stats"><div class="stat stat-blue"><div class="stat-icon">${iconSvg('target')}</div><div class="k">Target Harian</div><strong>${target} menit</strong><small>Atur target di Kalender</small><div class="mini-track"><i style="width:${Math.min(100,Math.round((state.minutes%Math.max(1,target))/target*100))}%"></i></div></div><div class="stat stat-green"><div class="stat-icon">${iconSvg('check')}</div><div class="k">Progres Keseluruhan</div><strong id="overall">${pct}%</strong><small id="donecount">${done} dari ${total} modul selesai</small><div class="mini-track"><i style="width:${pct}%"></i></div></div><div class="stat stat-purple"><div class="stat-icon">🏆</div><div class="k">Streak Belajar</div><strong>${new Set(state.focusSessions.map(x=>x.date)).size} hari aktif</strong><small>Hari belajar tercatat</small></div><div class="stat stat-amber"><div class="stat-icon">⭐</div><div class="k">Skill Mastery</div><strong>${Math.round(pct/10)}/10</strong><small>Terus tingkatkan kemampuan</small></div></section>
 <section class="dashboard-grid"><div class="panel dashboard-calendar"><div class="panelhead"><h2>${iconSvg('calendar')} Kalender Belajar</h2><button class="link" data-page="Kalender">Lihat semua →</button></div><div class="calendar-preview"><div class="mini-calendar"><div class="calendar-month">${today.toLocaleDateString('id-ID',{month:'long',year:'numeric'})}</div><div class="mini-days">${days.map(d=>`<b>${d}</b>`).join('')}${Array.from({length:offset},()=>'<i></i>').join('')}${Array.from({length:monthDays},(_,i)=>{let n=i+1,dt=new Date(today.getFullYear(),today.getMonth(),n),key=dateKey(dt);return `<button class="${n===today.getDate()?'selected':''} ${state.agenda.some(a=>a.date===key)?'has-event':''}" data-date="${key}">${n}</button>`}).join('')}</div></div><div class="today-agenda"><h3>Jadwal Hari Ini</h3>${todayAgenda.length?todayAgenda.slice(0,4).map(a=>`<div class="agenda-item"><i></i><div><b>${esc(a.time||'Fleksibel')}</b><span>${esc(a.title)}</span><small>${a.duration||30} menit</small></div></div>`).join(''):'<p class="muted">Belum ada jadwal. Tambahkan agenda belajarmu.</p><button class="btn secondary" data-page="Kalender">Buat jadwal</button>'}</div></div></div>
 <div class="panel roadmap-panel"><div class="panelhead"><h2>${iconSvg('route')} Roadmap Pembelajaran</h2><button class="link" data-page="Roadmap">Lihat detail →</button></div><div class="roadmap-list">${roadmap.map((c,i)=>`<div class="roadmap-step"><span class="roadmap-dot ${progress(c.id)===100?'complete':progress(c.id)>0?'current':''}">${progress(c.id)===100?'✓':i+1}</span><div><b>${esc(c.name)}</b><small>${progress(c.id)===100?'Selesai':progress(c.id)>0?'Sedang dipelajari':'Belum dimulai'} · ${progress(c.id)}%</small></div><button class="link" data-course="${c.id}">Buka</button></div>`).join('')}</div><div class="roadmap-art">🎓 <span>Setiap langkah kecil membawamu lebih dekat ke tujuan.</span></div></div>
 <div class="panel current-learning"><div class="panelhead"><h2>${iconSvg('book')} Materi yang Sedang Dipelajari</h2><button class="link" data-page="Ruang Belajar">Lanjutkan belajar →</button></div><div class="current-course"><div class="current-course-icon">${courseIconMarkup(active)}</div><div class="current-course-info"><b>${esc(active.name)}</b><span>${esc(next[0])}</span><div class="bar"><i style="width:${progress(active.id)}%"></i></div><small>${progress(active.id)}% · ${active.units.length} modul</small></div><button class="btn" data-course="${active.id}">Lanjutkan</button></div></div>
 <div class="panel progress-panel"><div class="panelhead"><h2>${iconSvg('progress')} Ringkasan Progres</h2><button class="link" data-page="Progres">Lihat detail →</button></div><div class="progress-overview"><div class="progress-ring"><b>${pct}%</b><small>Total progres</small></div><div class="progress-legend"><span><i></i> Modul selesai <b>${done}</b></span><span><i></i> Belum selesai <b>${total-done}</b></span><span><i></i> Waktu belajar <b>${Math.floor(state.minutes/60)} jam</b></span></div></div></div>
 <div class="panel quick-panel"><div class="panelhead"><h2>⚡ Akses Cepat</h2></div><div class="quick-links"><button data-page="Perpustakaan">${iconSvg('library')}<span>Perpustakaan</span></button><button data-page="AI Tutor">${iconSvg('spark')}<span>AI Tutor</span></button><button data-page="Kalender">${iconSvg('calendar')}<span>Kalender</span></button><button data-page="Laporan">${iconSvg('report')}<span>Laporan</span></button><button data-page="Pengaturan">${iconSvg('settings')}<span>Pengaturan</span></button></div></div><div class="quote-panel"><span>💡</span><b>“Ilmu adalah kunci untuk membuka pintu masa depan yang lebih baik.”</b><small>My Academic Space</small></div></section>`;
}
function taskList(){return state.tasks.length?state.tasks.map((t,i)=>`<div class="task ${t.done?'done':''}"><input type="checkbox" data-task="${i}" ${t.done?'checked':''}><span style="flex:1">${esc(t.text)}</span><button class="link" data-delete-task="${i}">Hapus</button></div>`).join(''):'<div class="empty">Belum ada target. Tambahkan satu tugas kecil untuk memulai.</div>'}
function coursePage(){
 const active=window.activeCourse&&courses.find(c=>c.id===window.activeCourse);
 if(active){return `<div class="course-detail-head"><button class="link" id="backCourses">← Semua jalur belajar</button><span class="tag">${esc(active.level)}</span><h1>${esc(active.name)}</h1><p>${esc(active.desc)}</p><div class="detail-progress"><div class="bar"><i style="width:${progress(active.id)}%"></i></div><b>${progress(active.id)}% selesai</b></div></div><div class="panel"><div class="panelhead"><h2>Materi dan Modul Pembelajaran</h2><span class="tag">${active.units.length} modul</span></div>${active.units.map((u,i)=>`<article class="module-card"><div class="module-number">${state.done[active.id+'-'+i]?'✓':String(i+1).padStart(2,'0')}</div><div class="module-content"><h3>${esc(u[0])}</h3><p>${esc(u[1])}</p><div class="module-practice"><b>Latihan praktik</b><span>${esc(u[2])}</span></div><label class="module-complete"><input type="checkbox" data-unit="${active.id}-${i}" ${state.done[active.id+'-'+i]?'checked':''}> Tandai modul selesai</label></div></article>`).join('')}</div><div class="notice">Materi di atas merupakan kerangka belajar dan latihan praktik. Video, bank soal, ujian terjadwal, serta penilaian otomatis memerlukan konten dan sistem evaluasi lanjutan.</div>`}
 let selectedLevel=window.courseLevel||'',query=(window.courseQuery||'').toLowerCase();let visible=courses.filter(c=>(!selectedLevel||c.level===selectedLevel)&&(!query||(c.name+' '+c.desc+' '+c.units.flat().join(' ')).toLowerCase().includes(query)));
 return `<section class="courses-heading"><div><span class="eyebrow">TEMUKAN MINATMU</span><h1>Explore Learning Paths</h1><p>Jelajahi jalur pembelajaran dengan beragam topik dan tingkat kesulitan.</p></div><span class="course-count">${courses.length} jalur tersedia</span></section><div class="course-searchbar">⌕ <input class="field" id="courseSearch" placeholder="Cari topik, deskripsi, atau kategori..." value="${esc(window.courseQuery||'')}"></div><div class="course-filter-row"><span>Jelajahi semua jalur</span><select class="field" id="courseLevel"><option value="">Semua level</option><option value="Pemula" ${selectedLevel==='Pemula'?'selected':''}>Pemula</option><option value="Menengah" ${selectedLevel==='Menengah'?'selected':''}>Menengah</option><option value="Mahir" disabled>Mahir · belum tersedia</option></select></div><div class="learning-card-grid">${visible.map(c=>`<article class="learning-card" data-course-level="${c.level}"><div class="learning-card-meta"><span class="tag">${c.id==='english'||c.id==='thai'||c.id==='german'?'LANGUAGE':c.id==='freelance'?'CAREER':'TECHNICAL'}</span><span class="level-pill">${esc(c.level)}</span></div><h2>${esc(c.name)}</h2><p>${esc(c.desc)}</p><div class="learning-card-footer"><span>▤ ${c.units.length} Modul</span><span>${progress(c.id)}% selesai</span></div><div class="bar"><i style="width:${progress(c.id)}%"></i></div><button class="btn" data-course="${c.id}">Lihat Jalur</button></article>`).join('')||'<div class="empty">Tidak ada jalur yang sesuai dengan pencarian.</div>'}</div>`;
}
function library(){let imported=storedBooks.map(b=>b.path),q=window.bookQuery||'',cat=window.bookCategory||'',filtered=books.filter(b=>(b.title+' '+b.category).toLowerCase().includes(q.toLowerCase())&&(!cat||b.category.includes(cat))),cloudFiltered=cloudBooks.filter(b=>(b.name||'').toLowerCase().includes(q.toLowerCase()));return `<div class="panel"><div class="panelhead"><div><h2>Perpustakaan Digital</h2><p class="small">${books.length} buku katalog · ${storedBooks.length} file lokal · ${cloudBooks.length} file cloud</p></div><div class="row"><label class="btn" for="zipInput">Impor ZIP</label><input id="zipInput" type="file" accept=".zip" multiple hidden><label class="btn secondary" for="pdfInput">Upload file</label><input id="pdfInput" type="file" accept="application/pdf,.pdf,.epub,.txt,.md,.html" multiple hidden></div></div><div class="notice">File dapat dibaca dari perangkat. Jika Supabase Storage sudah disiapkan dan koneksi cloud aktif, kamu juga dapat mengunggah dokumen ke ruang cloud pribadi. Maksimum upload cloud 50 MB per file.</div><div class="row" style="margin:14px 0"><input class="field" id="bookSearch" placeholder="Cari judul atau kategori buku..." value="${esc(q)}" style="flex:1"><select class="field" id="bookCategory"><option value="" ${!cat?'selected':''}>Semua kategori</option>${[...new Set(books.map(b=>b.category))].map(c=>`<option ${cat===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><h3>File pribadi · Perangkat ini</h3><div class="bookgrid" id="bookGrid">${storedBooks.map(b=>`<article class="book"><div class="cover">${/\.pdf$/i.test(b.name)?'PDF':'DOC'}</div><h3>${esc(b.name)}</h3><small>File lokal · ${((b.blob?.size||0)/1048576).toFixed(2)} MB</small><div class="row"><span class="tag">Di perangkat</span><button class="btn" data-openbook="${esc(b.path)}">Buka</button><button class="btn secondary" data-upload-local="${esc(b.path)}" ${cloudLibraryAvailable()?'':'disabled'}>Upload cloud</button></div></article>`).join('')||'<div class="empty">Belum ada file lokal. Upload PDF, EPUB, TXT, Markdown, atau HTML.</div>'}</div><h3>File pribadi · Supabase Cloud</h3><div class="bookgrid">${cloudFiltered.map(b=>`<article class="book"><div class="cover">CLOUD</div><h3>${esc(b.name)}</h3><small>Cloud · ${(b.size/1048576).toFixed(2)} MB</small><div class="row"><span class="tag">Tersinkron</span><button class="btn" data-opencloud="${esc(b.path)}">Buka</button><button class="btn ghost" data-deletecloud="${esc(b.path)}">Hapus</button></div></article>`).join('')||'<div class="empty">Belum ada file di cloud atau cloud belum terhubung.</div>'}</div><h3>Katalog Reading Gallery</h3><div class="bookgrid">${filtered.map(b=>{let has=imported.includes(b.path);return `<article class="book" data-book-category="${esc(b.category)}"><div class="cover">${b.category.startsWith('A.')?'DATA':b.category.startsWith('B.')?'OFFICE':b.category.startsWith('C.')?'WEB':b.category.startsWith('D.')?'CAREER':'LANG'}</div><h3>${esc(b.title)}</h3><small>${esc(b.category)} · ${(b.size/1048576).toFixed(1)} MB</small><div class="row">${has?'<span class="tag">Tersedia</span>':'<span class="tag">Belum diimpor</span>'}<button class="btn ${has?'':'secondary'}" data-openbook="${esc(b.path)}" ${has?'':'disabled'}>${has?'Baca':'Belum tersedia'}</button></div></article>`}).join('')||'<div class="empty">Katalog tidak menemukan buku yang cocok.</div>'}</div></div>`}

function reader(){if(!selectedBook)return library();let isCloud=selectedBook.source==='cloud';return `<div class="panel"><div class="panelhead"><div><button class="link" id="backLibrary">← Perpustakaan</button><h2>${esc(selectedBook.title)}</h2></div><span class="tag">${isCloud?'Cloud Reader':'Reader'} ${state.readingDone[selectedBook.path]?'· Selesai dibaca':''}</span></div><div class="reader-toolbar row"><button class="btn secondary" id="readerLight">Terang</button><button class="btn secondary" id="readerDark">Gelap</button><button class="btn secondary" id="readerBookmark">Bookmark halaman</button><span class="small" id="bookmarkList">Bookmark: —</span></div><iframe class="reader" id="pdfFrame" title="Pembaca dokumen" sandbox="allow-scripts"></iframe><div class="row" style="margin:12px 0"><label class="small">Halaman</label><input class="field" type="number" min="1" id="readPage" value="${state.lastRead[selectedBook.path]||1}" style="width:90px"><button class="btn secondary" id="savePage">Simpan halaman</button><button class="btn" id="finishBook">Tandai selesai</button></div><label><b>Catatan pribadi</b></label><textarea class="field note" id="bookNote" placeholder="Tulis pemahaman, pertanyaan, atau rangkuman...">${esc(state.notes[selectedBook.path]||'')}</textarea><button class="btn secondary" id="saveNote" style="margin-top:8px">Simpan catatan</button></div>`}

function roadmap(){return `<div class="panel"><div class="panelhead"><h2>🧭 Roadmap Pembelajaran</h2><span class="tag">Disusun dari koleksi buku</span></div><div class="notice">Urutan rekomendasi untuk membangun keterampilan yang bisa dipraktikkan: spreadsheet → website → portofolio. Bahasa dipelajari sebagai jalur pendamping dengan latihan konsisten.</div>${courses.map((c,idx)=>`<div class="lesson"><div class="row"><h3 style="flex:1">${idx+1}. ${courseIconMarkup(c)} ${c.name}</h3><span class="tag">${progress(c.id)}% selesai</span></div><div class="bar"><i style="width:${progress(c.id)}%"></i></div><p>${c.desc}</p><p><b>Modul:</b> ${c.units.map(u=>u[0]).join(' → ')}</p><button class="btn secondary" data-course="${c.id}">Buka jalur</button></div>`).join('')}</div>`}
function calendar(){let base=new Date(),d=new Date(base.getFullYear(),base.getMonth()+calendarMonthOffset,1),year=d.getFullYear(),month=d.getMonth(),first=d.getDay(),days=new Date(year,month+1,0).getDate(),names=['Min','Sen','Sel','Rab','Kam','Jum','Sab'],chosen=window.calendarDate||localDate(),agendas=state.agenda.filter(a=>a.date===chosen),monthTitle=d.toLocaleDateString('id-ID',{month:'long',year:'numeric'});return `<div class="grid contentgrid"><div class="panel"><div class="panelhead"><h2>Kalender Belajar</h2><div class="row"><button class="btn secondary month-nav" data-monthmove="-1" aria-label="Bulan sebelumnya">←</button><b>${monthTitle}</b><button class="btn secondary month-nav" data-monthmove="1" aria-label="Bulan berikutnya">→</button></div></div><div class="calendar">${names.map(n=>`<div class="day"><b>${n}</b></div>`).join('')}${Array.from({length:first},()=>'<div></div>').join('')}${Array.from({length:days},(_,i)=>{let date=`${year}-${String(month+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<button class="day ${date===chosen?'today':''} ${state.agenda.some(a=>a.date===date)?'has-agenda':''}" data-date="${date}">${i+1}</button>`}).join('')}</div><div class="row" style="margin-top:14px"><label class="small">Pilih tanggal</label><input id="agendaDate" type="date" class="field" value="${chosen}"></div></div><div class="panel"><h2>Agenda · ${new Date(chosen+'T00:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}</h2><form id="agendaForm" class="tutor-form"><input id="agendaTitle" class="field" placeholder="Nama agenda belajar" required><div class="row"><input id="agendaTime" type="time" class="field"><input id="agendaDuration" type="number" min="5" step="5" value="30" class="field" style="width:100px" aria-label="Durasi menit"></div><button class="btn">Tambah agenda</button></form>${agendas.length?agendas.map(a=>`<div class="task"><div style="flex:1"><b>${esc(a.title)}</b><small class="small">${a.time||'Waktu fleksibel'} · ${a.duration||30} menit</small></div><button class="link" data-delete-agenda="${a.id}">Hapus</button></div>`).join(''):'<div class="empty">Belum ada agenda untuk tanggal ini.</div>'}<hr><h3>Target belajar</h3><div class="row"><input id="targetDaily" type="number" min="1" max="1440" class="field" value="${state.targets.daily}" aria-label="Target harian"><span class="small">menit per hari</span><button id="saveTarget" class="btn secondary">Simpan target</button></div><div class="row target-range"><label class="small">Target mingguan (menit) <input id="targetWeekly" type="number" min="1" class="field" value="${state.targets.weekly}"></label><label class="small">Target bulanan (menit) <input id="targetMonthly" type="number" min="1" class="field" value="${state.targets.monthly}"></label></div></div></div>`}

function progressPage(){let total=courses.reduce((n,c)=>n+c.units.length,0),completed=Object.values(state.done).filter(Boolean).length;return `<div class="panel"><div class="panelhead"><h2>Progress Pembelajaran</h2><span class="tag">${completed}/${total} modul</span></div><div class="progress-summary"><div class="progress-ring"><b>${Math.round(completed/total*100)}%</b><small>selesai</small></div><div><h3>${state.minutes} menit fokus</h3><p class="small">${state.tasks.filter(t=>t.done).length} target diselesaikan · ${state.tasks.filter(t=>!t.done).length} target aktif</p></div></div><div class="grid stats">${courses.map(c=>`<div class="stat"><div class="k">${c.name}</div><strong>${progress(c.id)}%</strong><div class="bar"><i style="width:${progress(c.id)}%"></i></div><small>${c.units.filter((u,i)=>state.done[c.id+'-'+i]).length}/${c.units.length} modul</small></div>`).join('')}</div></div>`}
function reports(){let done=Object.values(state.done).filter(Boolean).length,total=courses.reduce((n,c)=>n+c.units.length,0),byCourse=courses.map(c=>`<div class="report-row"><span>${esc(c.name)}</span><div class="bar"><i style="width:${progress(c.id)}%"></i></div><b>${progress(c.id)}%</b></div>`).join('');let week=[];for(let i=6;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);let date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;week.push({date,label:d.toLocaleDateString('id-ID',{weekday:'short'}),minutes:state.focusSessions.filter(x=>x.date===date).reduce((n,x)=>n+(Number(x.minutes)||0),0)})}let max=Math.max(25,...week.map(x=>x.minutes));let weeklyChart=`<div class="weekly-chart" role="img" aria-label="Grafik waktu fokus tujuh hari">${week.map(d=>`<div class="chart-day"><div class="chart-track"><i style="height:${Math.max(2,d.minutes/max*100)}%"></i></div><b>${d.minutes}</b><small>${d.label}</small></div>`).join('')}</div>`;return `<div class="panel"><div class="panelhead"><h2>Laporan & Analitik</h2><button class="btn secondary" id="exportData">Ekspor JSON</button></div><div class="grid stats"><div class="stat"><small>Modul selesai</small><strong>${done}/${total}</strong></div><div class="stat"><small>Total waktu fokus</small><strong>${state.minutes} mnt</strong></div><div class="stat"><small>Target diselesaikan</small><strong>${state.tasks.filter(t=>t.done).length}</strong></div><div class="stat"><small>Agenda terjadwal</small><strong>${state.agenda.length}</strong></div></div><h3>Waktu fokus · 7 hari terakhir</h3>${weeklyChart}<h3>Perkembangan per jalur</h3>${byCourse}<h3>Ringkasan aktivitas</h3><p class="small">${state.focusSessions.length} sesi fokus tercatat · ${state.agenda.length} agenda tersimpan · ${done} modul selesai dari ${total} modul. Grafik hanya menampilkan sesi fokus yang benar-benar tercatat.</p><div class="row"><button class="btn secondary" id="exportData">Backup data JSON</button><label class="btn ghost" for="backupInput">Import backup</label><input hidden id="backupInput" type="file" accept="application/json"></div></div>`}

function tutor(){return `<div class="panel"><div class="panelhead"><div><h2>🤖 AI Learning Tutor</h2><p class="small">Guru belajar pribadi · mode integrasi bertahap</p></div><span class="tag" id="aiStatus">Status belum diuji</span></div><div class="notice">AI Tutor memakai backend Vercel. Fitur ini baru aktif setelah endpoint dan Environment Variables penyedia AI dikonfigurasi. API key tidak disimpan di browser.</div><div id="tutorChat" class="tutor-chat">${tutorMessages.length?tutorMessages.map(m=>`<div class="chat-msg ${m.role==='user'?'user':'assistant'}"><b>${m.role==='user'?'Kamu':'AI Tutor'}</b><div>${esc(m.content).replace(/\n/g,'<br>')}</div></div>`).join(''):'<div class="empty">Mulai dengan bertanya tentang materi yang sedang kamu pelajari.</div>'}</div><div class="row ai-check"><button type="button" class="btn secondary" id="testAI">Tes koneksi AI</button><span class="small" id="aiStatusText">Status AI akan diperbarui setelah tes atau pertanyaan pertama.</span></div><form id="tutorForm" class="tutor-form"><textarea id="tutorInput" class="field" rows="3" maxlength="8000" placeholder="Contoh: Jelaskan fungsi VLOOKUP dari dasar dengan contoh sederhana..." required></textarea><div class="row"><select id="tutorCourse" class="field">${courses.map(c=>`<option value="${c.id}">Konteks: ${c.name}</option>`).join('')}</select><button class="btn" id="tutorSend" type="submit">Kirim pertanyaan →</button><button class="btn secondary" id="tutorClear" type="button">Hapus percakapan</button></div></form><p class="small">Catatan: versi ini belum mengirim isi PDF otomatis ke AI. Fitur Ask My Book memerlukan proses ekstraksi teks dan indeks dokumen tersendiri.</p></div>`}
function settings(){let p=state.preferences;return `<section class="settings-shell"><aside class="settings-menu"><h2>Pengaturan Pribadi</h2><p>Atur profil, keamanan, dan preferensi aksesibilitasmu.</p><button class="settings-tab active" data-settings-target="theme-settings">${iconSvg('settings')} Preferensi</button><button class="settings-tab" data-settings-target="language-settings">${iconSvg('globe')} Bahasa</button><button class="settings-tab" data-settings-target="notification-settings">${iconSvg('user')} Aksesibilitas & Notifikasi</button><button class="settings-tab" data-settings-target="integration-settings">${iconSvg('cloud')} Integrasi & Data</button></aside><div class="settings-content"><div class="settings-section" id="theme-settings"><h2>Tema</h2><p>Pilih tampilan My Academic Space sesuai kenyamananmu.</p><div class="preference-options"><label class="preference-card ${p.theme==='system'?'chosen':''}"><input type="radio" name="themeChoice" value="system" ${p.theme==='system'?'checked':''}><span class="pref-symbol">◐</span><b>Ikuti perangkat</b><small>Otomatis mengikuti pengaturan perangkat.</small></label><label class="preference-card ${p.theme==='light'?'chosen':''}"><input type="radio" name="themeChoice" value="light" ${p.theme==='light'?'checked':''}><span class="pref-symbol">☀</span><b>Terang</b><small>Tampilan cerah dengan kontras nyaman.</small></label><label class="preference-card ${p.theme==='dark'?'chosen':''}"><input type="radio" name="themeChoice" value="dark" ${p.theme==='dark'?'checked':''}><span class="pref-symbol">☾</span><b>Gelap</b><small>Tampilan redup untuk kondisi minim cahaya.</small></label></div></div><div class="settings-section" id="language-settings"><h2>Bahasa</h2><p>Atur bahasa antarmuka dan bahasa pembelajaran.</p><div class="settings-grid"><label class="setting"><span>Bahasa aplikasi</span><select class="field" id="appLanguage"><option value="id" ${p.appLanguage==='id'?'selected':''}>Bahasa Indonesia</option><option value="en" ${p.appLanguage==='en'?'selected':''}>English</option></select></label><label class="setting"><span>Bahasa pembelajaran</span><select class="field" id="learningLanguage"><option ${p.learningLanguage==='English'?'selected':''}>English</option><option ${p.learningLanguage==='Bahasa Indonesia'?'selected':''}>Bahasa Indonesia</option><option ${p.learningLanguage==='Deutsch'?'selected':''}>Deutsch</option><option ${p.learningLanguage==='ภาษาไทย'?'selected':''}>ภาษาไทย</option></select></label></div></div><div class="settings-section" id="notification-settings"><h2>Notifikasi & Aksesibilitas</h2><label class="notification-setting"><span><b>Pengingat belajar</b><small>Izinkan pengingat dan notifikasi aktivitas belajar.</small></span><input type="checkbox" id="notifications" ${p.notifications?'checked':''}></label></div><div class="settings-section" id="integration-settings"><h2>Integrasi & Data</h2><div class="integration-row"><div><b>Supabase Cloud</b><small>Progress cloud dan Cloud Library menggunakan konfigurasi Supabase.</small></div><span class="tag" id="settingsCloudStatus">Memeriksa…</span></div><div class="integration-row"><div><b>AI Tutor</b><small>Endpoint dan kredensial AI diatur melalui Environment Variables Vercel.</small></div><button class="btn secondary" data-page="AI Tutor">Buka AI Tutor</button></div><div class="row settings-actions"><button class="btn" id="savePreferences">Simpan perubahan</button><button class="btn secondary" id="exportData">Backup JSON</button><label class="btn secondary" for="backupInput">Import JSON</label><input hidden id="backupInput" type="file" accept="application/json"><button class="btn ghost" id="clearProgress">Reset progress</button></div></div></div></section>`}
function render(){let content=page==='Dashboard'?dashboard():page==='Ruang Belajar'?coursePage():page==='Perpustakaan'?(selectedBook?reader():library()):page==='AI Tutor'?tutor():page==='Kalender'?calendar():page==='Roadmap'?roadmap():page==='Progres'?progressPage():page==='Laporan'?reports():settings();$('#app').innerHTML=`<div class="layout">${nav()}<main class="main">${header()}${content}</main></div><nav class="mobilebar">${['Dashboard','Ruang Belajar','Perpustakaan','Roadmap','Progres'].map((x,i)=>`<button data-page="${x}">${iconSvg(['home','book','library','route','progress'][i])}<br>${x}</button>`).join('')}</nav>`;bind();renderStats();const cs=cloudStatus();const se=$('#settingsCloudStatus');if(se)se.textContent=cs.connected?'Terhubung':cs.configured?'Perlu pemeriksaan':'Belum dikonfigurasi';if(selectedBook&&page==='Perpustakaan')loadReader()}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;selectedBook=null;render()});document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>{window.activeCourse=b.dataset.course;page='Ruang Belajar';render()});$('#backCourses')?.addEventListener('click',()=>{window.activeCourse=null;render()});$('#addTask')?.addEventListener('click',()=>{let v=$('#newTask').value.trim();if(v){state.tasks.push({text:v,done:false});save();render()}});document.querySelectorAll('[data-task]').forEach(e=>e.onchange=()=>{state.tasks[+e.dataset.task].done=e.checked;save();render()});document.querySelectorAll('[data-delete-task]').forEach(e=>e.onclick=()=>{state.tasks.splice(+e.dataset.deleteTask,1);save();render()});document.querySelectorAll('[data-unit]').forEach(e=>e.onchange=()=>{state.done[e.dataset.unit]=e.checked;save();render()});$('#zipInput')?.addEventListener('change',e=>importZips([...e.target.files]));$('#pdfInput')?.addEventListener('change',e=>importPdfs([...e.target.files]));const applyBookFilter=()=>{let q=(window.bookQuery||'').toLowerCase(),category=window.bookCategory||'';document.querySelectorAll('.book').forEach(el=>{let cat=el.dataset.bookCategory||'',categoryMatch=!cat||!category||cat.includes(category),searchMatch=!q||el.textContent.toLowerCase().includes(q);el.classList.toggle('hidden',!categoryMatch||!searchMatch)})};$('#bookSearch')?.addEventListener('input',e=>{window.bookQuery=e.target.value;applyBookFilter()});$('#bookCategory')?.addEventListener('change',e=>{window.bookCategory=e.target.value;applyBookFilter()});document.querySelectorAll('[data-openbook]').forEach(b=>b.onclick=async()=>{let rec=await dbGet(b.dataset.openbook);if(!rec){toast('File PDF belum diimpor');return}selectedBook=books.find(x=>x.path===b.dataset.openbook)||{path:rec.path,title:rec.name};page='Perpustakaan';render()});document.querySelectorAll('[data-opencloud]').forEach(b=>b.onclick=async()=>{try{toast('Mengunduh file cloud…');let blob=await cloudDownloadFile(b.dataset.opencloud);selectedBook={path:b.dataset.opencloud,title:cloudBooks.find(x=>x.path===b.dataset.opencloud)?.name||b.dataset.opencloud.split('/').pop(),name:cloudBooks.find(x=>x.path===b.dataset.opencloud)?.name||b.dataset.opencloud.split('/').pop(),source:'cloud',blob};page='Perpustakaan';render()}catch(err){toast(err.message||'Gagal membuka file cloud')}});document.querySelectorAll('[data-upload-local]').forEach(b=>b.onclick=async()=>{try{let rec=await dbGet(b.dataset.uploadLocal);if(!rec?.blob)throw new Error('File lokal tidak ditemukan.');b.disabled=true;b.textContent='Mengunggah…';let file=new File([rec.blob],rec.name,{type:rec.blob.type||'application/octet-stream'});await cloudUploadFile(file);cloudBooks=await cloudListFiles();toast('File berhasil diunggah ke cloud');render()}catch(err){toast(err.message||'Upload cloud gagal')}finally{b.disabled=false}});document.querySelectorAll('[data-deletecloud]').forEach(b=>b.onclick=async()=>{if(!confirm('Hapus file ini dari Supabase Cloud?'))return;try{await cloudDeleteFile(b.dataset.deletecloud);cloudBooks=await cloudListFiles();toast('File cloud dihapus');render()}catch(err){toast(err.message||'Gagal menghapus file')}});$('#backLibrary')?.addEventListener('click',()=>{selectedBook=null;render()});$('#savePage')?.addEventListener('click',()=>{state.lastRead[selectedBook.path]=Math.max(1,+$('#readPage').value||1);save();toast('Halaman terakhir disimpan')});$('#finishBook')?.addEventListener('click',()=>{state.readingDone[selectedBook.path]=true;save();render();toast('Buku ditandai selesai')});$('#saveNote')?.addEventListener('click',()=>{state.notes[selectedBook.path]=$('#bookNote').value;save();toast('Catatan disimpan')});$('#startTimer')?.addEventListener('click',startTimer);$('#resetTimer')?.addEventListener('click',()=>{clearInterval(timerTick);timerTick=null;timerSecs=1500;if($('#timer'))$('#timer').textContent='25:00'});$('#testAI')?.addEventListener('click',async()=>{let btn=$('#testAI'),status=$('#aiStatus'),text=$('#aiStatusText');btn.disabled=true;btn.textContent='Menguji…';if(status)status.textContent='Menguji';if(text)text.textContent='Mengirim permintaan tes ke backend…';try{if(typeof window.masAskTutor!=='function')throw new Error('Adapter AI belum termuat.');await window.masAskTutor([{role:'user',content:'Balas singkat: koneksi AI Tutor My Academic Space berhasil.'}]);if(status)status.textContent='Terhubung';if(text)text.textContent='Tes berhasil. AI memberikan respons.';toast('AI Tutor berhasil merespons')}catch(err){if(status)status.textContent='Tidak terhubung';if(text)text.textContent=err.message||'Tes koneksi gagal. Periksa konfigurasi backend.';toast(err.message||'Tes AI gagal')}finally{btn.disabled=false;btn.textContent='Tes koneksi AI'}});$('#tutorForm')?.addEventListener('submit',async e=>{e.preventDefault();const input=$('#tutorInput'),button=$('#tutorSend'),text=input.value.trim();if(!text)return;if(typeof window.masAskTutor!=='function'){toast('Modul AI belum siap. Muat ulang halaman.');return}tutorMessages.push({role:'user',content:text});localStorage.setItem('mas-tutor-history',JSON.stringify(tutorMessages));input.value='';button.disabled=true;button.textContent='Menghubungi AI…';render();try{const selected=$('#tutorCourse');const courseName=courses.find(c=>c.id===selected?.value)?.name||'Pembelajaran umum';const outgoing=tutorMessages.slice(-20).map((m,i)=>i===tutorMessages.length-1&&m.role==='user'?{...m,content:`Konteks jalur belajar: ${courseName}.\nPertanyaan: ${m.content}`} : m);const answer=await window.masAskTutor(outgoing);tutorMessages.push({role:'assistant',content:answer});localStorage.setItem('mas-tutor-history',JSON.stringify(tutorMessages));if($('#aiStatus'))$('#aiStatus').textContent='Terhubung';if($('#aiStatusText'))$('#aiStatusText').textContent='AI berhasil menjawab pertanyaan terakhir.';}catch(err){tutorMessages.pop();localStorage.setItem('mas-tutor-history',JSON.stringify(tutorMessages));toast(err.message||'AI Tutor belum tersedia');}finally{render();const b=$('#tutorSend');if(b){b.disabled=false;b.textContent='Kirim pertanyaan →'}}});$('#tutorClear')?.addEventListener('click',()=>{tutorMessages=[];localStorage.removeItem('mas-tutor-history');render()});$('#tutorGo')?.addEventListener('click',()=>{page='Ruang Belajar';render()});$('#copyTutor')?.addEventListener('click',()=>navigator.clipboard?.writeText('Jelaskan [topik] dari dasar, gunakan contoh sederhana, berikan satu latihan, lalu nilai jawabanku berdasarkan langkah dan hasilnya.').then(()=>toast('Template disalin')));document.querySelectorAll('#exportData').forEach(b=>b.onclick=exportBackup);$('#backupInput')?.addEventListener('change',importBackup);$('#clearProgress')?.addEventListener('click',()=>{if(confirm('Reset seluruh progress modul? Tugas dan buku tidak dihapus.')){state.done={};save();render()}});$('#globalSearch')?.addEventListener('keydown',e=>{if(e.key==='Enter'){window.bookQuery=e.target.value;page='Perpustakaan';selectedBook=null;render()}});const applyCourseFilter=()=>{let q=(window.courseQuery||'').toLowerCase(),level=window.courseLevel||'';document.querySelectorAll('[data-course-level]').forEach(card=>card.classList.toggle('hidden',!!level&&card.dataset.courseLevel!==level||!!q&&!card.textContent.toLowerCase().includes(q)))};$('#courseSearch')?.addEventListener('input',e=>{window.courseQuery=e.target.value;applyCourseFilter()});$('#courseLevel')?.addEventListener('change',e=>{window.courseLevel=e.target.value;applyCourseFilter()});document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{window.calendarDate=b.dataset.date;let chosen=new Date(b.dataset.date+'T00:00:00'),base=new Date();calendarMonthOffset=(chosen.getFullYear()-base.getFullYear())*12+chosen.getMonth()-base.getMonth();render()});document.querySelectorAll('[data-monthmove]').forEach(b=>b.onclick=()=>{calendarMonthOffset+=Number(b.dataset.monthmove)||0;let m=new Date(new Date().getFullYear(),new Date().getMonth()+calendarMonthOffset,1);window.calendarDate=`${m.getFullYear()}-${String(m.getMonth()+1).padStart(2,'0')}-01`;render()});$('#agendaDate')?.addEventListener('change',e=>{window.calendarDate=e.target.value;let chosen=new Date(e.target.value+'T00:00:00'),base=new Date();calendarMonthOffset=(chosen.getFullYear()-base.getFullYear())*12+chosen.getMonth()-base.getMonth();render()});$('#agendaForm')?.addEventListener('submit',e=>{e.preventDefault();state.agenda.push({id:Date.now(),date:window.calendarDate||localDate(),title:$('#agendaTitle').value.trim(),time:$('#agendaTime').value,duration:+$('#agendaDuration').value||30});save();render()});document.querySelectorAll('[data-delete-agenda]').forEach(b=>b.onclick=()=>{state.agenda=state.agenda.filter(a=>String(a.id)!==b.dataset.deleteAgenda);save();render()});$('#saveTarget')?.addEventListener('click',()=>{state.targets.daily=Math.max(1,+$('#targetDaily').value||60);state.targets.weekly=Math.max(1,+$('#targetWeekly').value||state.targets.daily*7);state.targets.monthly=Math.max(1,+$('#targetMonthly').value||state.targets.daily*30);save();toast('Target harian diperbarui')});document.querySelectorAll('[data-settings-target]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.settings-tab').forEach(x=>x.classList.toggle('active',x===b));document.getElementById(b.dataset.settingsTarget)?.scrollIntoView({behavior:'smooth',block:'start'})});$('#savePreferences')?.addEventListener('click',()=>{state.preferences={theme:document.querySelector('input[name=themeChoice]:checked')?.value||state.preferences.theme,appLanguage:$('#appLanguage').value,learningLanguage:$('#learningLanguage').value,notifications:$('#notifications').checked};save();applyTheme();toast('Preferensi disimpan')});document.querySelectorAll('input[name=themeChoice]').forEach(r=>r.addEventListener('change',()=>{document.querySelectorAll('.preference-card').forEach(c=>c.classList.toggle('chosen',c.querySelector('input').checked));state.preferences.theme=r.value;applyTheme()}));$('#readerLight')?.addEventListener('click',()=>$('#pdfFrame').classList.remove('reader-dark'));$('#readerDark')?.addEventListener('click',()=>$('#pdfFrame').classList.add('reader-dark'));$('#readerBookmark')?.addEventListener('click',()=>{let p=+$('#readPage').value||1;state.bookmarks=state.bookmarks||{};state.bookmarks[selectedBook.path]=[...new Set([...(state.bookmarks[selectedBook.path]||[]),p])].sort((a,b)=>a-b);save();$('#bookmarkList').textContent='Bookmark: '+state.bookmarks[selectedBook.path].join(', ')});applyBookFilter?.();applyCourseFilter?.();}
function startTimer(){if(timerTick)return;if(timerSecs<=0)timerSecs=25*60;timerTick=setInterval(()=>{timerSecs--;let el=$('#timer');if(el)el.textContent=String(Math.floor(timerSecs/60)).padStart(2,'0')+':'+String(timerSecs%60).padStart(2,'0');if(timerSecs<=0){timerSecs=0;clearInterval(timerTick);timerTick=null;state.minutes=(Number(state.minutes)||0)+25;state.focusSessions.push({date:localDate(),minutes:25,completedAt:new Date().toISOString()});save();toast('Sesi fokus selesai. Istirahat sejenak!')}},1000)}
async function importPdfs(files){let allowed=['pdf','epub','txt','md','html'],imported=0;for(let f of files){let ext=f.name.split('.').pop().toLowerCase();if(!allowed.includes(ext)){toast(`${f.name}: format tidak didukung`);continue}if(f.size>200*1024*1024){toast(`${f.name}: file lokal maksimal 200 MB`);continue}let path='uploads/'+f.name;await dbPut({path,name:f.name,blob:f});imported++;}storedBooks=await dbAll();toast(`${imported} file berhasil diimpor ke perangkat`);render()}
async function importZips(files){if(!window.JSZip){toast('Library ZIP belum termuat. Periksa koneksi internet.');return}for(let f of files){try{if(f.size>200*1024*1024)throw new Error('ZIP maksimal 200 MB');toast('Membaca '+f.name+'…');let zip=await JSZip.loadAsync(f);let pdfs=Object.values(zip.files).filter(x=>!x.dir&&x.name.toLowerCase().endsWith('.pdf'));let count=0,skipped=0;for(let entry of pdfs){let blob=await entry.async('blob');if(blob.size>200*1024*1024){skipped++;continue}let path=entry.name;await dbPut({path,name:path.split('/').pop(),blob});count++;}toast(`${f.name}: ${count} PDF diimpor${skipped?`, ${skipped} file >200 MB dilewati`:''}`)}catch(err){console.error(err);toast('Gagal membaca '+f.name+'. Coba satu ZIP lagi.')}}storedBooks=await dbAll();render()}
let readerObjectUrl=null;
async function loadReader(){let rec=selectedBook.source==='cloud'?{name:selectedBook.name,blob:selectedBook.blob}:await dbGet(selectedBook.path);if(!rec?.blob)return;if(readerObjectUrl)URL.revokeObjectURL(readerObjectUrl);readerObjectUrl=URL.createObjectURL(rec.blob);let url=readerObjectUrl,ext=(rec.name||'').split('.').pop().toLowerCase(),frame=$('#pdfFrame');if(['txt','md','html'].includes(ext)){frame.setAttribute('sandbox','');let txt=await rec.blob.text();frame.srcdoc=ext==='html'?`<!doctype html><meta charset=utf-8><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data: blob:; style-src 'unsafe-inline'"><style>body{font:16px/1.7 system-ui;padding:24px}</style>${sanitizeDocumentHtml(txt)}`:`<!doctype html><meta charset=utf-8><style>body{font:16px/1.7 system-ui;padding:24px;white-space:pre-wrap}</style>${esc(txt)}`}else if(ext==='epub'){frame.setAttribute('sandbox','allow-scripts');frame.srcdoc=`<!doctype html><html><head><meta charset=utf-8><style>html,body,#reader{height:100%;margin:0}#reader{padding:16px;box-sizing:border-box}</style><script src="https://cdn.jsdelivr.net/npm/epubjs/dist/epub.min.js"><\/script></head><body><div id="reader"></div><script>let book=ePub('${url}'),rend=book.renderTo('reader',{width:'100%',height:'100%'});rend.display();<\/script></body></html>`}else{frame.removeAttribute('sandbox');frame.src=url+(ext==='pdf'&&Number(state.lastRead[selectedBook.path])?`#page=${Number(state.lastRead[selectedBook.path])}`:'')}let marks=state.bookmarks?.[selectedBook.path]||[];$('#bookmarkList').textContent='Bookmark: '+(marks.length?marks.join(', '):'—')}
function sanitizeDocumentHtml(html){try{const parsed=new DOMParser().parseFromString(html,'text/html');parsed.querySelectorAll('script,iframe,object,embed,form,link,meta,base,style').forEach(n=>n.remove());parsed.querySelectorAll('*').forEach(el=>{for(const a of [...el.attributes])if(/^on/i.test(a.name)||['src','href','srcset','style'].includes(a.name))el.removeAttribute(a.name)});return parsed.body.innerHTML}catch{return esc(html)}}
function exportBackup(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='academic-space-backup.json';a.click();URL.revokeObjectURL(a.href)}
function importBackup(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!x||typeof x!=='object'||Array.isArray(x))throw new Error('');state.done=x.done&&typeof x.done==='object'?x.done:state.done;state.tasks=Array.isArray(x.tasks)?x.tasks:state.tasks;state.notes=x.notes&&typeof x.notes==='object'?x.notes:state.notes;state.lastRead=x.lastRead&&typeof x.lastRead==='object'?x.lastRead:state.lastRead;state.minutes=Math.max(0,Number(x.minutes)||0);state.agenda=Array.isArray(x.agenda)?x.agenda:state.agenda;state.targets={...state.targets,...(x.targets||{})};state.preferences={...state.preferences,...(x.preferences||{})};state.bookmarks=x.bookmarks&&typeof x.bookmarks==='object'?x.bookmarks:state.bookmarks;state.focusSessions=Array.isArray(x.focusSessions)?x.focusSessions:state.focusSessions;state.readingDone=x.readingDone&&typeof x.readingDone==='object'?x.readingDone:state.readingDone;save();render();toast('Backup berhasil dipulihkan')}catch{toast('File backup tidak valid')}};r.readAsText(f)}
function showCloudStatus(status){const el=$('#cloudStatus');if(el)el.textContent=status.message||'Status cloud tidak diketahui';const settingsEl=$('#settingsCloudStatus');if(settingsEl)settingsEl.textContent=status.connected?'Terhubung':status.configured?'Perlu pemeriksaan':'Belum dikonfigurasi'}
function applyTheme(){let t=state.preferences?.theme||'light';document.documentElement.dataset.theme=t==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):t}
async function init(){applyTheme();try{books=await fetch('/books.json').then(r=>r.json())}catch{books=[]}storedBooks=await dbAll();if(!window.JSZip){let s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js';document.head.append(s)}render();const cloud=await initializeCloud(showCloudStatus);if(cloud.configured&&!cloud.error){try{cloudBooks=await cloudListFiles()}catch(err){console.warn('Cloud library listing failed',err);cloudBooks=[]}}if(cloud.data&&typeof cloud.data==='object'){const remote=cloud.data;state.done={...(remote.done||{}),...(state.done||{})};state.tasks=[...(remote.tasks||[]),...(state.tasks||[])].filter((x,i,a)=>a.findIndex(y=>y.text===x.text&&!!y.done===!!x.done)===i);state.notes={...(remote.notes||{}),...(state.notes||{})};state.lastRead={...(remote.lastRead||{}),...(state.lastRead||{})};state.agenda=[...(remote.agenda||[]),...(state.agenda||[])].filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i);state.targets={...(remote.targets||{}),...(state.targets||{})};state.preferences={...(remote.preferences||{}),...(state.preferences||{})};state.bookmarks={...(remote.bookmarks||{}),...(state.bookmarks||{})};state.readingDone={...(remote.readingDone||{}),...(state.readingDone||{})};state.focusSessions=[...(remote.focusSessions||[]),...(state.focusSessions||[])].filter((x,i,a)=>a.findIndex(y=>y.completedAt===x.completedAt)===i);state.minutes=Math.max(Number(remote.minutes)||0,Number(state.minutes)||0);localStorage.setItem('mas-state',JSON.stringify(state));renderStats();scheduleCloudSave(state)}else if(cloud.configured&&!cloud.error){scheduleCloudSave(state)}showCloudStatus((await import('./services/cloud.js')).cloudStatus());render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})}
init();
